INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8399062', 'ENF: 21/01/2026 - Enf Eduardo: Paciente proveniente de Maria da Graça, 83 anos, com histórico de HAS, DM2, IC, DRC Dialítico e AVEs. Interna por ITU de repetição e distensão abdmonial.  Acamada, desorientada, pouco interativa. Em uso de SNE 45ml/h + VO. Fará 8 semanas de ATB (vanco), sem pendencias clínicas no momento. Segue em acompanhamento do EGAA. 25/02/2026 - Enfª Liziani: Paciente em processo de programação de alta hospitalar, Dialítica, necessitando ser regulada para clínica satélite de diálise, pois, não havia vaga no HFB. Converso com a Drª Michele da clínica de diálise sobre paciente e a mesma decidiu regulá-la pelo HFB (3ª/5ª e Sábado no 2º turno), Drª Laís da CM mista ciente. Converso com a filha da paciente, Cirlene, junto com Assistente social do EGAA Rosiane que orientou quanto a solicitação de transporte para HD após alta. Drª Michele forneceu relatório médico para prosseguir com o pedido de transporte e informado a Drª Laís a necessidade de relatório também pela clínica médica. Segue sendo acompanhada pelo EGAA. 16/04/2026 - Enfª Liziani: Paciente em processo de desospitalização, sendo acompanhada pelo EGAA, solicito acompanhamento com a Terapia Ocupacional, converso com a TO Lúcia que irá avaliar a paciente. SESO:  25/02/2026: abordagem em conjunto com a enfermeira Liziani. Foi realizada articulação com a médica Michele, nefrologista, a qual informou que a paciente foi inserida para realização de hemodialise no HFB após a alta (sessões as terças, quintas e sábados das 11 até as 15h. Conversamos sobre esta inserção com a filha Cirlene, a qual foi orientada sobre acesso ao transporte sanitário eletivo via câmara de litígios e sobre aluguel social de cama hospitalar. Solicitamos confecção de relatório médico à Dra. Laís, que informou nao ser a referência para a paciente, mas se comprometeu a repassar para a equipe de referência. 21 98776-4294 Cirlene, filha/ 21 99864-6141 Magno, filho. A filha informou que na alta a paciente retornará a casa e será cuidado pelo filho Magno, residem em Maria da Graça. A filha reside em D. Caxias.  Comentou que a paciente permanece com cuidadora formal 3 vezes na semana e que nos demais dias ela e seu irmão se revezam nos cuidados.  Aguardamos confecção do relatório médico para prosserguirmos com a orientação para acesso ao transporte.  Em 26/02/206, Rosiane: recebo relatório médico comi indicação de ambulância comum para as sessões de hemodialise, repasso documento a filha e oriento a agendar o atendimento na CRLS.  Vou ao setor de transporte verificar se o serviço é oferecido elo HFB, sou informada de que o setor de ambulância não presta esse serviço. Em 24/03/2026, Rosiane: repasso laudo informando inviabilidade da paciente de sedestação. Aguardo retorno da médica da CAP. Em 08/04 foi realizada conferência com o casal de filhos da idosa, paciente estava na CM mista. Ambos informaram que irão se dividir nos cuidados, a filha Cirlene ficará resposnável por realizar a parte burocrática para viabilizar o transporte para as sessões de HD, o filho cuidará no domicílio após a alta. De acordo com equipe médica, a paciente não tem condições de transporte em carro comum, pois não se mantém sentada. Desta forma, orientamos sobre a necessidade de laudo médico que ateste tal condição, a fim de que a demanda seja judicializada. Em 13/04 o laudo foi disponibilizado para a filha (conforme informa a AS Vanessa). Em 16/04/2026: Enfermeira Liziani informa que a paciente está conseguindo se manter sentada. Neste sentido, indico rediscussão com equipe médica da ala feminina sobre viabilidade de transporte em carro comum e em caso positivo, emissão de novo laudo, tendo em vista que o anterior aponta necessidade de transporte em ambulância. 24/04/2026: Laudo para solicitação de TAXI RIO entregue pelo médico Carlos Vinícius ao Enfº Eduardo e AS Rosiane do EGAA. Laudo entregue à filha de paciente pela AS da Nefroligia. Em 28/04/2026, Rosiane:  recebo retorno da filha Cirlene, a qual informa que  esteve na CRLS e foi exigido o agendamento do atendimento. Mediante a informação conflitante, uma vez que a CRLS orienta que o agendamento não se faz necessário em caso de pacientes internados. Conduta: farei contato com a CRLS a fim de checar a conduta aplicada ao caso concreto. Cirlene: 21 98776-4294. Em 15/05: a filha Cirlene informou que esteve na CLRS e conseguiu solicitar o Transporte eletivo sanitário para as sessões de HD. Em 26/05/2026, Rosiane: A filha informa que recebeu informações da equipe médica sobre declínio do quadro clínico e suspensão de alta, tendo a filha reportado a informação a CRLS.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('163119', '19/06/2026 - EnfªLiziani: paciente deu entrada na emergência com quadro de afasia e desorientação súbita, estava acompanhada por familiares, não sabem informar início do quadro, mas viram a paciente sem alterações pela última vez em 13/05/26. HPP: HAS com uso irregular de medicação e IAM há 12 anos, com realização de revascularização. Apresenta afasia, sem déficit motores periféricos, com força preservada nos 4 membros. Invasões: IOT em VM, AVC em VSD, CVD e SNE. Infusões: Propofol, FTN e Nipride. Foi realizada tentativa de desmame de sedoanalgesia sem sucesso em 09/06. Segue sob vigilância rigorosa, sem previsão de alta por ora.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('2231704', '15/06/2026: Enfª Liziani: Paciente com histórico de adenocarcinoma, sendo atendido pela gastro para investigação e possível retossigmoisdoscopia para elucidação do quadro clínico, porém, após discussão do caso será acompanhada pela clínica médica. Realizado articulação com o NIR para movimentação de paciente para clínica médica masculina, sendo autorizado.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8429434', '09/07/26 - Enfª Liziani: Paciente acompanhada pela cirurgia vascular. com necrose de MIE, emtratamento de pneumonia bacteriana, sendo abordada cirurgicamente para amputação suprapatelar de MIE, evoluindo com EAP Hipertensivo, no pós op interna no CTI. No momento estável. Em ATB terapia com Tazocin, AVP em VSCD (03/07)', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8429434', 'TQT (03/07), em uso de cateter e O2 à 3 Lts. Segue em vigilância contínua.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8417830', '09/07/26 - Enfª Liziani: Paciente pós op tardio de RTU de bexiga (28/05/26) e Cistectomia (30/06/26), acompanhada pela Urologia. IH: Oriunda da emergência com queixa de hematúria, leucocitose e dor. Feito uso de ATB sem melhora. BX de (29/05): Carcinoma urotelial de alto grau. USG de vias urinárias evidenciou massa em bexiga, sendo submetida à procedimento cirúrgico e no momento encontra-se em vigilância no CTI, em ATB terapia.', NOW(), NOW())
