INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8421512', '28/05/2026 - Enfª Liziani: Paciente interna com quadro de crise hipertensiva, fez USG de vias urinárias em 25/05/26. Em ATB terapia com Tazocin. Em avaliação pela Nefrologia sobre possibilidade de realizar biópsia renal. Discutido em round transferência de paciente para a clínica médica masculina para investigação de HAs secundária pelos Staffs e residentes de medicina. Solicitado transferência de leito no NIR.  SESO, 01/06/2026, Rosiane: Em round foi informado que o paciente fará antibiótico até julho/2026, não deabula e sente dor ao sentar. Casado, reside com filha Ive de 30 anos e com a esposa Marcia de 52 anos em Olaria. Trabalhador autonomo, deu entrada no Benefício por Incapacidade Temporária. 21 96470-0141 Ive. SESO E ENF: em round de 09/06: paciente com quadro de espondilodiscite, tinha RNM para hoje, mas não conseguiu realizar devido piora clínica. Equipe médica encaminhará nova solicitação do exame ao NIR. De acordo com a AS Jete, paciente tem família presente e nao apresenta QS para a alta. No momento sem previsão.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('2054019', '18/06/2026 - Enfª Liziani: Paciente PO de TX renal doador falecido, realizado em 17/05/2026, com quadro de DGF, doppler do enxerto com alteração. Evoluiu com quadro de dor precordial durante HD em 31/05, realizou CATE em 16/06/26. Em ATB terapia. Aguarda TC e ECOTT.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8243725', '03/07/26 - Enfª Liziani: Paciente TX renal desde de 2023, interna na nefrologia com quadro de diarréia crônica há cerca de 3 meses associada à piora da função renal. Aguarda resultado da biópsia renal. Aguarda laudo da endoscopia e colonoscopia realizados dia 25/06/26. Angina ISSIII, sendo solicitado CATE e realizado dia 30/06/26. Segue', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8336103', '16/06/2026 - Enfª Liziani: Paciente TX renal, doador falecido - DPO: 14/04/2026. Após transplantectomia + rafia de bexiga, com complicação de fístula urinária e ferida op com URC (31/05) Acinetobacter baumanii. Mantendo tratamento com Polimixina B, Vancomicina e Ampicilina + SULB. Em melhora gradativa da coleção na TC 29/05. Paciente em uso de SNE. Com NPT. HD 3x na semana. Segue aguardando melhora do quadro clínico para alta hospitalar.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8390556', 'ENF: 04/05/2026 - Enfª Liziani: Paciente CA de bexiga submetido à RTU recente, admitida com quadro de sepse urinária, evoluindo com insuficiência respiratória aguda, apresentando broncoespasmo e congestão, tratado com VNI e broncodilatador. Portador de ICEFEP e DPOC, em corticoterapia VO e inalatória, associada a LABA, dependente de O2 suplementar em baixa concentração. Portador de ureterolitíase e CA de bexiga T1 sem invasão de muscular. Em acompanhamento pela Urologia que tentará encaixe em mapa cirúrgico de 05/05/26. Com parecer pendente para a pneumologia, procuro o setor e converso com a pneumo Drª Wilza que foi ao leito e avaliou o paciente. SESO, em 18/05, Rosiane: paciente restrito ao leito, aguarda proposta pela urologia amanhã. Jete presente no round, não mencionou questão social para alta. 22/05/2026 - Enfª Liziani: Paciente com cirurgia de urgência à ser realizada pela Urologia, porém, com necessidade de vaga em CTI no PO. Articulo com NIR reserva de vaga, cirurgia programada para hoje (22/05). SESO, em 09/06/2026: em round, paciente em uso de O2, CP/final de vida, sem margem de  melhora para ir para casa.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8382864', '19/05/2026 - Enfª Liziani: Paciente interna com quadro de febre à esclarecer e artralgia. HPP Tuberculose em fevereiro de 2025. RNM cardíaco aguardando agendamento por solicitação VIA/NIR. Prescrito exame de cultura de urina micobacter não tuberculose. Realizo contato com o responsável pelo laboratório para agilizar exame prescrito, oriento ao Drº Tales, médico que acompanha o paciente, quanto a coleta de amostra, armazenamento e entrega de exame de acordo com informação do laboratório. 28/05/2026 - Enfª Liziani: Paciente aguardando RNM cardíaca via regulação SISREG/NIR HFB, para elucidação de quadro clínico e continuidade do tratamento. Pela cirurgia torácica, sem indicação de abordagem por ora. Transmito o caso para AS da ala para orientação quanto aos trâmites para agilizar o exame.  SESO e ENF, 09/06/2026 em round: paciente com febre a esclarecer, aguarda transferência para o INC e resultado de urinocultura, sem previsão de alta. Em 06/07, SESO: reside em Itaguaí com mae e 3 irmaos. Aguarda transferência ainda?', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8413091', 'ENF: 16/04/2026 - Enfª Liziani: Paciente interna com queixa de dor abdominal à esclarecer. HPP: Síndrome colestática em investigação', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8413091', 'colangite tratada', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8413091', 'anemia. Fez ATB terapia, hemotransfusão, corticoterapia crônica com desmame iniciado 16/04. USG de abdome  e TC contraste de abd total (24/03), Colangio RNM (16/03). Com aprecer pela gastro-hepato: Diagnóstico diferencial - síndrome de Mirizzi x tumor de ampola de vater. Solicitado EcoEDA e à depender do resultado será realizado CPRE. Aguarda resultado de marcadores de autoimunidade coletados 15/04. Eco EDA agendada para hoje (16/04). 04/05/2026 - Enfª Liziani: Paciente com ColangioRNM, exame externo, agendada para 08/05 às 09h, equipe médica e de enfermagem que o acompanha está ciente. Parecer da cirugia geral pendente para realização de biópsia, converso com a residente da CG Ana Marques e o procedimento será realizado após Colangio RNM. 22/05/2026 - Enfª Liziani: Paciente com indicação de CPRE, no momento não está sendo realizado no HFB, está regulado no SER, forneço o número da regulação à residente médica Samantha que solicitou para orientar a família no processo de judicialização de procedimento.  SESO: 26/05/2026: CHECO INSERÇÃO DO PACIENTE VIA NIR PARA REALIZAÇÃO DE CPRE E ORIENTO SOBRE JUDICIALIZAÇÃO. FAMILIAR DO PACIENTE IRÁ AMANHA (27/05) NO PLANTÃO DO JUDICIÁRIO, SOLICITO EMISSÃO  DE LAUDO MÉDICO NA DATA DE AMANHÃ. Em 01/06/2026: paciente com CPRE já judicializada. 25/06/2026 - Enfª Liziani: Paciente ainda aguardando CPRE regulada via NIR/SER. Comn parecer pendente pela otorrino. Feito contato com a residente da otorrino, será realizado exame endoscópico nasal no ambulatório, porém, sugerem solicitação de parecer pela endoscopia se há suspeita de candidíase esofágica. Comunico à clínica médica as orientações da otorrino.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8038125', 'SESO, 06/07/2026: fez CPRE? pendência: visitar leito hoje para verificar questões para desospitalização.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8401430', 'ENF: 09/04/26 - Enfª Liziani: Paciente com histórico de DM2, HAS, teve dois episódios de AVE (2017 e 2021) com sequelas de hemiplegia à D. Veio encaminhada do hospital Municipal Rocha Faria com urgência dialítica, para realização de cateterismo. Durante internação evoluiu com ICS comn HMC de 29/01 + para MSSA. Fez ATB terapia. Interna no setor da CM aguardando regulação par clínica satélite de HD. Em HD 3x /semana com programação de novo CDL  para 09/04. Será discutido com a Nefrologia possibilidade de diálise peritoneal, se não for possível, será feito laudo para judicializar transporte de HD. HMC do dia 23/03: MSSA, em ATB terapia guiado (por 14 dias). Em parecer da ortopedia solicitado RX de ombro D. Em acompanhamento pela fisioterapia, fonoaudiologia e psicologia. Em round multidisciplinr foi discutido necessidade de avaliação pela TO. Entro em contato com a TO Lúcia e a mesma irá atender o paciente. 04/05/2026 - Enfª Liziani: Articulado em conjunto com AS Rosiane do EGAA, atendimento com a Enfª da clínica de diálise peritoneal e a esposa e filha de paciente para conversar sobre o procedimento e sanar as dúvidas para decidir sobre a realização do mesmo. Drª Daniella da CM masculina ciente, será dia 05/05/2026 às 09h.SESO:   07/01/2026 A.S. Vanessa Peixoto: Paciente veio transferido do Hospital Municipal Rocha Faria, sem nenhum tipo de informação  sobre seu quadro clínico . Foi feito contato por parte deste escritório e solicitado a cópia do prontuário do paciente. Na data de hoje foi repassado por parte deste setor o prontuário do paciente via e-mail para a equipe médica da sala amarela, no setor da emergência. 31/03/2026 AS VANESSA PEIXOTO: Realizo busca ativa no prontuário do paciente e converso com assistente social da ala para trocar informações à respeito do tempo de permanência no hospital. A assistente social, Tercia informa que o paciente encontra-se aguardando transporte para poder vir dialisar no hospital e que a equipe do serviço social já orientou a família e bem como acionou a secretaria de saúde informando sobre o caso. 24/04/2026 AS VANESSA PEIXOTO: Realizo contato com esposa para falar sobre importancia de treinamento com equipe de enfermagem para dialise peritoneal. Em 30/04, AS Rosiane e Enf. Liziani: realizamos conversa com  a esposa, Sra. Rosilene, a fim de orientá-la sobre a pertinência da diálise peritonial, considerando a qualidade de vida e a complexidade que envolve a locomoção do paciente, que se encontra restrito ao leito. Pontuamos que não está padronizado o acesso a ambulância para procedimentos eletivos, de forma que seria uma questão a judicializar. A esposa relatou receio quanto as condições do seu domicílio e do manuseio do aparelho, no entanto, concordou em pacrticipar, junto à filha, de reunião para maiores esclarecimentos sobre a realização do procedimento no domicílio.  A esposa está disponível nas segundas, tercças e quartas. Oirentamos também sobre procuração do INSS e  articulamos laudo médico. Desta forma, agendaremos reunião para terça ou quarta (05 ou 6/5) 21 97157-4546 Rosineide.  SESO E ENF, round de 09/06: paciente realizou procedimento para inserção de dispositivo para diálise peritoneal, está guardando agenda para iniciar treinameno de familiares.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8420586', 'SESO: Em 06/07: reside com a esposa Luci em São João de Meriti, esposa presente como acompanhante. Seso informa que realizou orientação sobre CRLS (checar finalidade e andamento.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8416226', 'ENF: Em 06/05: Foi informado em round que o paciente encontra-se com sequelas neurológicas e que a filha informou a equipe médica que não levaria o paciente para casa. 07/05: Segundo o médico Lucca o paciente tem histórico de AVE hemorrágico, com sequelas motoras e cognitivas severas e internou por provável pneumonia broncoaspirativa. Paciente não interage, não verbaliza, não deambula  e tem GTT como via nutricional. Paciente em finitude com piora do quadro neurológico e sem resposta a ATB de largo espectro.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8416226', 'Realizo o acolhimento e escuta da filha do paciente (Vitória Silva do Nascimento - 24 anos), junto com a AS Tércia, que relata cuidar do pai há oito anos, desde que sua mãe faleceu. Vitória informa que seu pai entrou num quadro depressivo e vários surtos psicóticos, quando perdeu a esposa, ficando sete anos sem sair de casa. Vitória alega estar sozinha nos cuidados com o pai, pois seu irmão (Luca Silva do Nascimento - 32 anos) não possui bom relacionamento com o pai e que seu tio Célio (irmão do paciente) também não participa dos cuidados com o paciente. Na atualidade Vitória não consegue cuidar do pai no seu domicílio, por questões físicas e financeiras. Paciente é aposentado, recebe um salário mínimo, reside de aluguel (valor R$560,00) sozinho, próximo a sua residência. Informo a Vitória que solicitaremos  um leito em unidade de cuidados prolongados conforme exposto a ela  pela equipe médica e que o  serviço social está a disposição para qualquer esclarecimento. Em 08/05: Inicio o preenchimento do formulário para transferência para leitos de cuidados prolongados (necessário dar continuidade),solicito relatório social ( AS Jete e Tércia) e relatório médico que justifique a transferência ( médico Lucca). Deixo cópias dos documentos do paciente para digitalizar.  Procuro as Tércia para conversar sobre notificação ao MP acerca do caso deste paciente, no entanto a colega estava em atendimento.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8416226', 'SESO: Em 12/05/2026, Rosiane: converso em round sobre questão de regulação para para cuidados prolongados, sinalizo que o paciente não se enquadra no perfil e importância de que  a desospitalização seja discutida com a presença do Serviço Social tendo e vistas as questões sociais que envolvem o caso. Preenchimento de formulário suspenso. Filha foi reabordada pelas ASs Maria Helena e Jete e pela Enf, Liziani. Foi acordado que a filha iniciará organização para o cuidado no domicílio. Posteriormente a filha informou que se encontra adoecida por Tuberculose e que não ofertará cuidados ao pai. Em 18/05, Rosiane: em round, assistente social Jete presente informou que a filha não compareceu mais ao hospital, o caso será encaminhado ao MP (definição de cuidador). Em abordagem no leito, paciente gemente, sem condições de diálogo. 21 96577-6160 Vitória, filha. Em 01/06/2026, Rosiane: apresento em round o fluxo para desospitalização e vaga em leito de cuidados prolongados, defini-se que trata-se de solicitação de abrigamento. Solicito emissão de sumario de alta, a médica Samantha informou que amanhã fará o documento.  Encaminho também e-mail ao PLID para localização do filho Lucas.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8416226', 'SESO: em round de 09/06: equipe médica informa que estão avaliando alimentação via oral e retirada da GTT, paciente com melhora na interação. Filha esteve ontem conversando com a AS Jete, manteve posicionamento sobre impossibilidade de cuidados no domicílio. Explico para equipe sobre processo de solicitação de vaga em abrigamento da prefeitura e necessidade de sumário de alta para dar prosseguimento ao processo. Filha ficou de vir hoje conversar com equipe médica. SESO: Em 15/06/2026, Rosiane: realizo abordagem no leito, paciente acordado, lúcido, orientado e interagindo. Refere que recebeu visita do irmão. Pede para falar com a filha Vitória e por este motivo faço chamada de vídeo, a interação foi positiva e o paciente demonstrou procupação com a saúde da filha.  A GTT foi retirada, e a médica informou que fará o sumário de alta amanhã. A filha informou que esta semana virá ao HFB.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('1387163', 'ENF: 29/10 Vigilancia intensiva.  Pac. em vigilância  04/10 Reabilitação cardiaca. 20/08 Aguardando tc de crânio. Em 07/04/26 - Enfª Liziani: Paciente interna com quadro de EAP hipertensivo, DAC multivascular. Em ATB terapia com mero 16/03 + POli 29/03. Dispositivos: CVD + GTT + TQT + PICC em MSE. Infusões: Dieta enteral e Noradrenalina. Segue em cuidados com a acomissão de curativo para tratamento de úlcera de panturrilha com exposição de osso e tendão. Em regulação para transferência hospitalar via NIR. SESO 02/07/2025 IZABEL: REALIZADA VISITA AO LEITO. PACIENTE RECEBEU A VISITA DO FILHO CRISTIANO. EM ABORDAGEM SOCIAL O FILHO RELATOU QUE O PACIENTE É CASADO (ESPOSA ANTONIA), TEM 02 FILHOS, É APOSENTADO, RESIDE EM BONSUCESSO COM O FILHO (ANDERSON) E A ESPOSA. REFERENTE A SAÚDE, FILHO CIENTE QUE AGUARDA REAGENDAMENTO DE CIRURGIA. PACIENTE TEM LIMITAÇÃO AUDITIVA DEVIDO SEQUELA DE AVC (SIC - FILHO). APÓS ESCUTA, ACOLHO E DISPONIBILIZO SETOR. TEL: (21) 99821-0770 ( CRISTIANO - FILHO)', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8417616', 'SESO, em round: paciente idosa, apresenta dependência de cuidados TQT, teve GTT cancelada devido a infecção. Quanto a questão social: reside em Magé, sem filhos, possui apenas a irmã  Maria de Fátima também idosa a qual está providenciando a curatela. Em cuidados proporcionais traçados com a família. Após procedimento de GTT será pensado plano para desospitalização, conforme progredir o quadro clínco.  SESO, em round de 07/07: paciente com perspectiva de realizar GTT hoje, precisa de fisioterapia respiratória, apresenta LP em sacra. Pelo Serviço Social: rede de suporte composta pela irmã Maria de Fátima e a sobrinha Roberta, residem em Magé. A irmã está providenciando a curatela, mas não referiu impeditivo para a alta. 99555-7610 Maria de Fátima, 99736-3064 Roberta, sobrinha.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8301440', 'SESO, em round 29/06: avaliação social pendente, pela medicina TC de pescoço + coluna hoje, EDA pendente de agendamento. 08/07/26 - Enfª Liziani: Paciente interna com quadro de sarcoidose e lombalgia. HPP de bóssio tireóideo. Em investigação e tratamento pela CM. Aguarda USG de abdome. Converso com a fisioterapiapara acompanhamento de paciente. Pelo SESO: familiares presentes.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8423357', 'SESO, em round de 15/06 - Rosiane: paciente DRC prévia, apresenta ITU, é deficiente visual, está restrita ao leito. De acordo com a AS Jete, a paciente possui rede de suporte para a alta.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8190464', 'seso, em round 29/06: pct com AVC prévio, agitada, contida, aguarda parecer da psiquiatria e TC de controle (craneo) sem data agendada. Reside em Ramos, possui as filhas Camila e Alexandra. Avaliação social pendente. Em 07/07, SESO e ENF Liziani, round: paciente com provavel demencia vascular, com quadro clínico estável, foi sinalizada como desospitalização.  AS Ricardo  informou que entrevistou a filha Camila, com a qual a paciente reside. Faço contato com Camila para tratar de desospitalização, a filha relata que receberá a  paciente no domicílio, mas que enfrenta questões financeiras , pois deixou de trabalhar. Refere que a paciente tem também os filhos Carlos, Silvio e Alexandra, que não participam dos cuidados e não contribuem financeiramente. A paciente é posentada, reside emimóvel alugado localizado em Ramos. CF de referência: Maria Cristina Roma. Verificar se equipe médica Conferência Familiar. 21 97101-2837,  Camila, 98160-1289 filha, 21 99847-2562 Carlos, 21 99490-8323 Silvio, 97155-3955 Alexandra.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('1250960', '29/06/2026 -SESO, Rosiane: paciente com previsão de alta para 03/07, agurda holter. Sua rede de suporte é restrita, tem uma sobrinha que já cuida de familiares idosos e um sobrinho referido com suporte para desospitalização. Seso agendou atendimento à nora para 02/07. SESO e Enf. Liziani, em 07/07:  paciente afasica, dieta via oral,precisa de reabilitação pela fisio e desbridamento de lesão por pressão para posterior desospitalização. De acordo com o AS Ricardo, a paciente tem como suporte filho e nora, que residem em Pilares. A nora é do lar e a principal cuidadora da paciente. Não há questão social para a alta. 21 98235-6057 Marcos, 21 98025-7636 Amélia, nora.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8421778', '16/06/2026 - Enfª Liziani: Paciente transferida para a Nefroclínica, proveniente do CTI. por descompensação glicêmica. Histórico recente de cesariana 30/05/26, sem intercorrências cirúrgicas. Reavaliando diálise diariamente e possível confecção de FAV. Em acompanhamento com a endocrinologia, paciente com discreta melhora de disglicemias. Segue aguardando estabilidade de quadro clínico e necessidade de HD contínua.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('7382123', 'SESO, em round de 15/06 - Rosiane: DRC transplantada, apresenta ansiedade e depressão, chegou na emergência catatônica, segue em investigação diagnóstica. Sem previsão de alta no momento. Em 29/06 - round: pct em investigação para demência, líquor foi enviado para o HTCFF, AGUARDA PARECER DA NEFRO E DA C. GERAL, bem como definição de via de alimentação. Reside em Rocha Miranda, tem esposo como referência. Pendência: pelo EGAA, avaliar plano para desospitalização.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8422486', '10/06/2026 - Enfª Liziani: Paciente internada na enfermaria da Nefrologia, com Eletroneuromiografia de MMII e MMSS solicitado via regulação/SER. Exame foi agendado para hoje (10/06), no Hospital Federal dos Servidores, às 08h, sendo informado a equipe da nefrologia para solicitação de transporte. 08/07/2026 - Enfª Liziani: Paciente com coleta de exames laboratoriais pendente, necessitando de urgência em resultado. Converso com a responsável pelo laboratório e solicito brevidade em coleta de resultado de exames, sendo realizado.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('5026539', 'SESO: 29/06/2026 - pct veio tranferida da CMC, foi biopsiada (rim) na semana passada, fara pulsoterapia. Reside em Acari, rede de suporte formada por esposo, pais e irmã. Sem questões para desospitalização no momento.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('1337114', 'SESO: Em 25/05/2026026, Rosiane: paciente com indicação de GTT, porém filha verônica se coloca contrária ao procedimento. A Sra. Elza era previamente independente para as atividades diárias de vida, residia sozinha, possui duas filhas mulheres e um filho homem. Para tratar da questão da GTT e da alta social, realizo articulação com o AS Ricardo, que agenda Conferência Familiar para  01/06 (segunda-feira). Hoje, 26/05, compareceu o filho acompanhado de uma irmã e de uma sobrinha, solicitando a reunião para hoje. Explico sobre o agendamento e que é necessário a articulação de equipe multi. Por insistência do filho, informo a residente Beatriz sobre a presença dos familiares, a médica indica necessidade de manter a conferência  multiprofissional. No entanto, enquanto eu estava dialogando com a médica, a família adentrou a enfermaria sem identificação pela recepção. Famíliares obtiveram informação quanto ao quadro clínico e a conferência foi mantida para 01/06 (segunda-feira) às 11h. SESO, Rosiane, 01/06/2026: participo de conferência familiar, estavam presentes o filho Denilson e a neta Graziela. Equipe multi: AS Ricardo, fono, nutricionista, psicóloga Ana e médica. Foi esclarecida sobre o procedimento de gastrostomia, bem como oquadro de dependência de cuidados para a alta, a fim de que a família se organize em torno do cuidado. Edmilson ficou de dar resposta quanto ao termo de consentimento para GTT na quarta-feira, após conversa com as irmãs Verônica e Magali. Denilson recebeu orientações também relativas a confecção de curatela. SESO, Rosiane, 03/06/2026: realizo orientações sobre o Serviço de Atendimento Domiciliar de Nova Iguaçu à filha Verônica, que informou que na alta a paciente será cuidada por ela em cômodo que será construído ao lado de sua casa, comentou que concoda com a GTT. Converso sobre previsão de alta após confecção de GTT.  98559-2943 Francarjo (esposo de Verônica), filha', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('1337114', '98945-8576 veridiana, filha da Verônica: 98945-8576. SESO: Em 15/09/2026, Rosiane: paciente em uso de antibiótico, será reavaliada para GTT ao término do esquema terapêutico. Assistente Social Ricardo informa em round que na alta a paciente será conduzida para a casa da filha verônica e que não há empecilho social para a alta. Em 29/06/2026, Rosiane: em round, paciente ccominfecção em ostio da GTT, sem previsão de alta pelo quadro infeccioso. AS Ricardo informa que o filho deu entrada na curatela em 19/06 e que o prazo para liberação do documento é de 15 a 30 dias.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8110761', '18/06/2026 - Enfª Liziani: Paciente interna com diagnóstico de tumor esofágico avançado com compressão causando disfagia progressiva. Possui prótese esofágica que está deslocada. Agendado abordagem pela CG para confecção de GTT e retirada de prótese, dia 19/06. Em avaliação para fechar cuidados paliativos. Regulada via SER/NIR para consulta oncológica. Em avaliação para radioterapia que se indicada poderá ser feita via ambulatorial. Paciente sendo acompanhada pelo EGAA para desospitalização. SESO -  29/06: pct fez gtt dia 25/06, fará TC de abdome amanhã e receberá alta se exame OK. Serviço Social não menciona QS para alta. 08/07/2026 - Enfª Liziani: Paciente com perda acidental de dispositivo de GTT, sendo acionado a CG e instalado sonda Folley nº 16 pelo Drº Breno. Paciente aguardando adaptação de GTT e treinamento para manusei pela família.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('7501940', 'SESO, 29/06: paciente proveniente da CMC no fds, reside na Nova Holanda, rede de suporte formada pelo esposo e filhos. Equipe médica ainda avaliará a paciente.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8416248', 'ENF: Em 11/05/26 - Enfª Liziani: Paciente interna com quadro de melena à esclarecer. Fez uma colonoscopia de 22/04 + EAS + URC (28/04). Pneumo ITU interrogada, paciente apresenta tosse produtiva. Em ATB terapia com Meropenem (D0 05/05). Aguardando carga viral para Hep C. Com CDL em VFD, TC de abdome e tórax realizada em 07/05, com solicitação de encaixe. Aguardando clínica satélite de HD. Aguardando resultado de PCR para solicitação de clínica satélite de HD. Converso com o responsável pelo laboratório solicitando brevidade em resultados de exame, sendo liberado posteriormente o resultado no sistema, equipe médica foi informada. SESO: Em 13/05/2026, Rosiane: de acordo com informações do round, há proposta de que a paciente realize HD no HFB 3X na semana. Abordo a paciente no leito, aparenta alguma desorientação,  verbaliza que deambula e tem tomado banho com auxil. Relata que na alta passará a residir com a filha Derluce em São João de Meriti. Não localizo ficha social no prontuário. Remeto avaliação ao Serviço Social da ala. 25/05/26 - Enfª Liziani: Paciente aguardando procedimento à ser realizado pela Urologia. Convesro com o médico urologista e abordagem está agendada para amanhã 26/05 encaixe ou entrará no mapa cirúrgico de quinta feira (28/05). Informo a equipe da clínica médica feminina. Discutido em round sobre regulação de paciente para clínica satélite de HD, paciente com dificuldades de conseguir regulação, sendo pendência para a alta hospitalar após realização de procedimento pela Urologia. Sugiro em round multi que seja conversado com a Nefrologia sobre possibilidade de paciente realizar a HD no HFB. SESO, em round de 15/06/2026: equipe médica menciona que a paciente tem feito diversas infecções pelo catéter de hemodiálise. Sem previsão de alta.  SESO: 29/06/2026, Rosiane: paciente aguardando parecer da URO desde a quinta-feira da semana passada para definir necessidade de cirurgia, precisa ser regulada para clinica de HD satélite. A Sra. Jorgina reside em São João de Meriti, possui as filhas Derluce e Denise. Na alta será acolhida pela filha Derluce (Rua Soldado bernardino da Silva, 277, casa, Penha.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('7450510', 'ENF E SESO, 09/06/2026: paciente aguarda painel reumatológico. A AS Jete informa que a família  é presente. Sem questões para a transição de cuidados no momento.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('1373852', '05/06/2026 - Enfª Liziani Platz: Paciente HAS, DM e DRC dialítico. Realizou angioplastia em 20/04 com instalação de 1 STent. Amputação em MIE e MID com lesão em hálux e pulsos filiformes de membros. Foi solicitado Doppler de MID agendado para o dia 15/06/26. Convesro no setor de agendamentos de exame e consigo reagendá-lo para hoje (05/06/26). Equipe da enfermaria de cardiologia cientes.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8083480', '16/06/2026 - Enfª Liziani: Paciente interna com queixa de febre/endocardite. Evolui com com leucocitose e TC sugestiva de pneumonia e embolização séptica. Em ATB terapia com Cefazolina + Clavulin. Realizado ECOTT 20/05, com sinais de endocardite, trombo móveis de aspecto emboligênico. Realizado toracocenteese de alívio/diag. com drenagem de líquido serohemático. Pela cirurgia cardiovascular indicado necessidade de melhora do quadro geral para realização de cirurgia.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8429427', 'SESO, 08/07/2026: realizado atendimento ao paciente, à Sara (apontada pelo paciente como irmã) e realizada articulação com o CREAS de São Pedro da Aldeia. Paciente sem referência de familiar consanguíneo, Sara e sua filha acolhiam o paciente, mas informam que atualmente não possuem condiçõe de ofertar os cuidados, bem como indicam que o hospital de origem informou que o paciente retornaria à unidade após avaliação no HGB. Repasso caso ao NIR.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8426601', 'SESO, 29/06/2026: em round foi informado que paciente aguarda laudo de RNM de coluna e desmame de O2, intensificação de fisioteraía respiratória. Sem previsão de alta no momento.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8427164', 'SESO, 29/06/2026: em round,  interna com pancreatite aguda,  aguarda parecer da Cirurgia Geral. Seso informa presença de rede de suporte, possui rede de suporte para desospitalização.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8429429', 'SESO, 30/06/2026: Em round de 29/06, a médica da hematologia informa que a paciente tem previsão de alta para sexta (03/06) e que há necessidade de realizar curativos diariamente. Abordo a paciente, que relata residir sozinha em Piabetá, que devido a piora do quadro clínico estava na casa do filho Michael em São João de Meriti. Possui a filha Roberta que mora em Campo Grande. Ao mencionar programação de alta, a paciente relata que se esente sem possibilidade de suporte familiar. Faço contato com os filho e solicito presença para  tratarmos da organização familiar. Em 30/06 realizamos atendimento conjunto com a AS Maria Helena, os filhos relataram a dificuldade da rede de Piabetá para acompanhamento dos curativos, comentaram que a paciente reside próxima de irmãs, mas que não recebe suporte e que a ex- sogra estava prestando  auxilio financeiro. Ambos levantaram dúvidas relativas ao diagnóstico da lesão ginecológica, trato com os curativos e seguimento ambulatorial. Em conversa com a hematologista, a mesma informa que a paciente dar seguimento ambulatorial o manejo ginecológico.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('1711508', 'SESO: 08/06/2026: de acordo com informações do round a paciente é DRC (ter, qui, sab), lúcida, restrita ao leito, iniciou antibiótico em 26/05 com previsão de término para 26/07. Em acompanhamento pela psicologia (ansiedade). Em 29/06/2026,  em round: a paciente aguarda parecer da gineco, fará FAV amanhã (30/06), está sem previsão de alta.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8410823', 'SESO: 29/06/2026: idosa, reside em São João de Meriti, aguarda CPRE e transferência para hospital oncológico. QT paliativa agendada para 09/07?  Rede de suporte composta por irmão, irmã e sobrinha, reside em São João de Meriti. 21 98134-3136 José, irmão / 21 98204-9991 Tais, sobrinha.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8322505', 'SESO, 15/06/2026, Rosiane: paciente interna com AVC, previamente DRC dialítica, sem previsão de alta no momento. Em 29/06: restrita ao leito, aguarda RM nero para iniciar ac plena, aguarda laudo de ecott e TC  de cranio.  Pendência: checar configuração familiar com o Serviço Social.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8424397', 'SESO, 08/07/2026, Rosiane: realizo abordagem no leito, a paciente estava acompanhada da filha Gabriele. A qual relatou que estava aguardando a dieta enteral, paciente já com sonda nasoenteral. Gabriele relata que a paciente se encontra bastante emagrecida pela baixa ingestão de alimentos por ceca de 30 dias. Refere que a mãe, pela hospitalização, piorou a questão da aceitação da alimentação e que acredita que o quadro seja de depressão. No momento, a paciente aguarda parecer da psiquiatria. Segue em acompanhamento pelo EGAA.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8426628', 'SESO: 29/06/2026 - paciente com previsão de ata até o final de semana (4 ou 5/07), está estável, aguarda ECO e Doppler, deambula com dificuldade, precisa de inserção em programa de obesidade. Em round oriento à equipe médica a referenciar para inserção em programa para regulação vuia UBS e PADI, tendo em vista a necessidade de fisioterapia.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8422196', 'SESO, 01/06/2026, Rosiane: paciente idoso de 61 anos, não está deambulando, sarcopenico.  ENF (09/06/2026) : em round foi informado que paciente aguarda cistoscopia agendda para 15/07, alta dependendo desde exame. A enfermeira Liz fez encaixe para hoje. Procedimento realizado!', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8411798', 'SESO, Rosiane, 02/06/2026: paciente estava inserida em Unidade de Acohimento da rede de atenção psicossocial,  encontra-se em pós operatório tardio de mandibulectomia, esvaziamento cervical e traqueostomia realizada em 28/04/2026, apresentava carcinoma escamoso de orofaringe, tem diagnóstico de esquizofrenia, revebeu alta hospitalar porém a instituição de acolhimento recusou verbalmente a recebê-la na alta. O Serviço Social encaminhou ofício a fim de  obter negativa oficial. Em conversa com as assistentes sociais Priscila e Sylvia, oriento a remeterem o caso a Assistencia Social,a fim de acolhimento,  solicitar PLID e em caso de negativa de acolhimento, notificar ao MP. SESO: Em 10/06, converso com a médica Jueline sobre preenchimento do formulário multiprofissional para solicitação de leito de cuidados prolongados. Ao final do plantão checo formulário, pendente apenas de preenchimento da nutricionista e do SESO. Solicito preenchimento dos respectivos profissionais. SESO: Em 15/06/2026, Rosiane: retio formulário preenchido para solicitação de transferência para leitos de cuidados prolongados. encaminho para o emial da regulacao.  Em 30/06, Rosiane: a assistente social Priscila informou que foi estabelecido novo fluxo para solicitação de vaga de acolhimento na Assistência: envio via setor jurídico do HFB. A solicitação foi encaminhada pelo Serviço Social ao Juridico e no momento, aguardamos retorno.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8377747', '20/10: Paciente sendo acompanhado pelo EGAA.  Solicitado acompanhamento pelo PADI. 07/10 Ag. vaga para enfermaria  pediatria.  15/08 Ag. parecer da gastro para proxima semana.  16/09  Solicitado acompanhamento pela Gastro ,CIPE,Nutrologia e comissão de curativo . SESO: 27/11/2025 - Rosiane: Inserção no Sisreg articulada pelo Egaa. 03/12/2025 - Rosiane: Em conjunto com a assistente social Izabel, abordamos Sttefany (mae) de Giovanna (paciente) a fim de verificar o andamento da inserção da paciente no PADI. A mãe relata que a equipe do PADI já realizou visita a Giovanna no HFB e que a visita do PADI no domicílio está agendada para próxima segunda-feira (08/12/25) . Comenta também que está recebendo assistência de advogado de ONG, o qual orientou que Stefani comparecesse a Câmara de Resolução de Litígios para solicitar home care, caso seja negado, a mãe deverá solicitar a negativa para que o advogado entre com processo judicial. A judicialização do alimento para NPT também foi orientada pelo advogado da ONG em caso de negativa pelo PADI ou Camara de Litígios. Sttefany irá amanhã resolver as pendências do seu título de eleitor e inserção da filha no Cadúnico. Oriento quanto ao endereço e horário de funcionamento. Foi fornecido laudo médico a Stefani a fim de que obtenha celeridade  no atendimento de suas demandas.  16/12/2025, Rosiane: recebo relatório médico do PADI, o documento aponta que a residência de Sttefany não atende aos critérios de segurança para ser atendido pelo programa. Diante da negativa, programo reabordar a mãe da paciente a fim de conversar sobre possibilidades. Repasso o relatório à  Dra. Lígia. Converso com a assistente social Bárbara sobre a necessidade de solicitar atendimento do DETRAN para Giovanna a fim de que a identidade da menor seja emitida, sendo essa a exigência para solicitação do BPC/LOAS. 18/12/2025, Rosiane: Realizo interconsulta com a médica Luana a fim de conversar sobre o relatório da avaliação do PADI, informo sobre encaminhamento da demanda para avaliação da Camara de Resolução de Litígiosa da Saúde, explico que conversarei hoje com Stefane sobre os pontos apontados no relatório como impedimentos para inclusão no PADI e falo sobre necessidade de relatório da nutróloga, uma vez que  a fórmula da NPT não é industrializada. A Dra. Luana informou que este relatório já foi entregue a Estefane. Sinalizou também que a paciente fez febre e que o quadro está instável no momento. Informo à médica também sobre o procedimento a ser adotado para acesso ao BPC. Fui ao leito abordar Estefane, mas ela estava dormindo junto a filha. Retornaremos em outro momento.  19/12/2025, Rosiane: Iniciada articulação com CRAS a fim de solicitar visita do referido órgão ao HFB para inclusão da paciente no Cadúnico e avaliação quanto à possibilidade de aluguel social. Mãe de Giovanna está articulando  mudança de casa. No entanto, localizada na mesma comunidade. Aguardo envio de endereço por Stefane à fim de repassar para coordenação do PADI. Converso com a médica coordenadora do PADI quanto a questão da fórmula da NPT e a médica informa que o maior empecilho é o local de moradia. O PADI já se encontra com o relatório da nutróloga. 19/12/2025, Rosiane: Iniciada articulação para contato com o CRAS a fim de solicitar visita do referido órgão ao HFB para inclusão da paciente no Cadúnico e avaliação quanto à possibilidade de aluguel social. Mãe de Giovanna está articulando  mudança de casa. No entanto, localizada na mesma comunidade. Aguardo envio de endereço por Stefane à fim de repassar para coordenação do PADI. Converso com a médica coordenadora do PADI quanto a questão da fórmula da NPT e a médica informa que o maior empecilho é o local de moradia. O PADI já se encontra com o relatório da nutróloga. Em 24/02/2025, Rosiane: desde a negativa do PADI realizei orientação quanto à necesidade de comparecimento a CRLS, a mãe realizou a triagem, via whatsapp, para agendamento de atendimento, porém não compareceu no referido órgão. Informa insegurança ao se ausentar da enfermaria, bem como  intercorrencias  no quadro clínico. Em 23/03/2026, Rosiane: discuto com médica Lígia sobre notificação ao MP com o intuito de mobilizar o suporte para a desospitalização, da mesma forma converso com o Serviço Social da ala e com Dayane, chefe do Serviço Social. Compartilho relatório para notificação com a chefia do Egaa. Em 01/04/2026, Rosiane: abordo novamente a genitora, a fim de sensibilizá-la para a importância de comparecer à Camara de Resolução de Litígios, como forma mais célere de acesso ao direito e desospitalização. Explico sobre a proposta de notificar ao MP, no entanto, sinalizo que provavelmente a resposta será morosa. Explico também que a CRLS pode emitir liminar para que Giovanna seja acompanhada pelo PADI ou  para obtenção de Home Care, conforme análise da equipe técnica do referido Órgão. Em 07/04/2026, Rosiane: a mãe esteve na CRLS, recebeu ofício com orientação sobre  laudo adequado, o doumento foi confeccionado pela médica assistente. Em 14/04 Giovanna foi submetida a cirurgia de reconstrução intestinal, após foi transferida para o CTI. Mãe programa retornar a CRLS quando o quadro estabilizar.   Em 05/05, paciente segue fazendo febre diariamente e por este motivo a mãe não conseguiu retornar a CRLS.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8410268', 'ENF: Em 11/05/26 - Enfª Liziani: Paciente interna com diagnóstico de síndrome de roubo por FAV.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8410268', 'DRC dialítica, HAS, DM. FAV em MSE. Em HD 3x por semana. PERMCATH de 26/03. HMC positiva para Enterococo, sendo iniciado Ampi + Genta (D0 06/05), sendo dolicitado troca de permcath. É acompanhada pela fonoaudiologia. De acordo com a fisioterapia não possui controle de tronco, paciente aguardando clínica satélite de HD, sendo necessário acompanhamento pelo SESO para auxiliar na orientação quanto ao transporte para HD pós alta. Em round multidisciplinar foi levantado o questionamento quanto a ausência de familiares que acompanhem a paciente, AS da ala Ricardo, tentando contato com familiares. Em 15/05/26 - Enfª Liziani: Paciente aguardando término de ATB para confecção de FAV pela nefrologia. Aguardando angio TC via regulação NIR. SESO: Em 05/05, Rosiane: Abordo paciente com vistas a desospitalização. Paciente previamente independente para as AVDS, atualmente apresenta dependência total de cuidados. Reside no Jacaré com a neta Thassia, que estava presente no momento da abordagem. Tássia mora com a senhora Sandra, sua atividade laborativa é no turno da noite. Relata que a paciente realizava hemodiálise na NefroClean (Rua São Luiz Gonzaga, 453 - Imperial de São Cristóvão), usava Uber para locomoção, mas durante um período teve cadastro no transporte eletivo/táxi Rio. A neta comenta que a clínica de diálise informou que poderá voltar a atender a paciente, pediu que a regulação faça contato para a vaga. A paciente possui a filha única Viviane e um neto menor de idade. Sinalizo para a neta sobre a importância da organização do cuidado no domicílio, tendo em vista o quadro de dependência, converso sobre o PADI. A neta relata que a paciente não tem feito terapia com frequência.  Em 07/05: Passagem inicia ATB em 06/05. Foi feito contato com a neta Tassia para agendar conferência familiar dia 13/05, às 14h, com equipe do serviço social e residente Fernanda. Contato Tassia 9909-43838. Em 13/05, Rosiane: conferência realizada com a médica Fernanda, serviço social ausente. A família foi informada sobre o quadro de dependência de cuidados e necessidade de organização. A neta Tássia e a filha Viviane relatam que estão cientes da dependência e que estão se organizando. Realizaram questionamentos quanto a fisioterapia, fono e sobre lesão por pressão. Explico que enquanto internada, a paciente recebe acompanhamento da equipe multiprofissional, porém não retornará a funcionalidade anterior e que não há critério para permanência na unidade hospitalar apenas para fisioterapia e fonoaudiologia. Sobre lesão por pressão, sinalizo que a avaliação é da comissão de curativos.  A médica explicou que a paciente tem questões clínicas a serem resolvidas ainda e que após resolução receberá alta. Converso com os familiares sobre o PADI.  Em 25/05,Rosiane: em round foi informado que a paciente não possuisustentação de tronco, converso sobre com a neta Tássia, que informa que a idosa sente desconforto ao sentar devido ao catéter colocado na virilha. Repasso informação para equipe. Em 26/05, Rosiane: realizada articulação com a fisioterapia para abordagem da paciente na presença da filha e neta que estavam na unidade. Há necessidade de definir se paciente tem condições de transporte sentada para as sessões de hemodiálise.  Em 08/06/2026, em round foi infomado que será solicitado parecer para verificar a viabilidade de HD peritoneal.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8422503', 'SESO: Rosiane, em 18/05: paciente recebe alta médica, porém sem suporte para cuidados no domicílio. De acordo com a AS Tamires (AS da emergência), a vizinha que realizava os cuidados relatou que não conseguirá manter. Foi agendada reunião com a vizinha para amanhã com a finalidade de trabalhar a alta. Possível caso de solicitação de vaga em abrigamento da prefeitura.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8416963', 'SESO, 17/06/2026 - Rosiane: em 16/06 a médica Lígia sinaliza previsão de alta para 07/07, necessidade de uso de marevan no pós alta. Realizo abordagem a genitora e avalio que famíllia vive em situação de extrema vulnerabilidade social (TERMINO DE REGISTRO DE AVALIAÇÃO PENDENTE)', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8388949', 'Em 14/12 - Enfª Liziani: Lactente, com diagnóstico de cardiopatia congênita, HIC III, hipotireioidismo, sepse e síndrome genética à esclarecer. Em 04/12 foi realizado aortoplastia + correção de CA no Hospital da Lagoa, retornando ao HGB em 13/11, apresentando LPP em região occiptal, ao qual foi solicitado parecer da comissão de curativo que seguiu prestando assistência a paciente. Aguardando: cariótipo/DNA (01/10) + USTF solicitado em 11/12 + Broncoscopia no IFF agendada para 18/12. Segue sendo acompanhada sendo EGAA. Em 13/02/26 - Enfª Liziani: Solicitado parecer para o EGGA para iniciar o processo de desospitalização de paciente. Realizado visita beira leito à lactente em conjunto com a AS Rosiane. Encontra-se estável, ventilando em AA por dispositivo TQT, O2 apenas SOS. Monitorização de SV, mantendo boa SAT 02. Dieta por GTT em BIC. Em investigação de possível síndrome. Pele íntegra, sem lesão. Não havia nenhum responsável no momento. Conversamos com a equipe de plantão e informamos que será iniciado processo de desospitalização, próxima intervenção será realizada pelo SESO do EGAA que recolheu os dados da responsável (mãe Beatriz) e entrará em contato para realização de entrevista social. Deixamos orientado com a equipe a necessidade de preenchimento de laudo com os insumos necessários para que o SESO possa dar entrada no programa Melhor em casa. Parecer já respondido e anexado em prontuário. Segue sendo acompanhada pelo EGAA. SESO: "Rosiane: Ainda em 13/02, foi realizada entrevista social com a Sra. Beatriz (28 anos): reside em casa alugada, localizada em Itaboraí, com Victor (23 anos/pai da paciente) e com o filho Theo de 4 anos. A mãe trabalhava por conta própria com extensão de cílios, parou de trabalhar devido ao quadro de saúde da paciente. Victor trabalha informalmente como atendente. A família recebe o Bolsa Família. A mãe comenta o elevado custo para deslocamento de sua residência até o HFB, não utiliza  transporte da prefeitura devido às dificuldades com os horários ofertados, refere que não consegue permanecer frequentemente como acompanhante, mas que quando está presente tem se empenhado na aprendizagem dos cuidados. Conduta: segue em acompanhamento para o processo de desospitalização, programo contato com o programa de atendimento domiciliar de Itaboraí após recesso de carnaval, bem como mapeamento da rede territorial para orientações sobre acesso aos insumos necessários a        o cuidado. Aguardo confecção de relatório médico e lista de insumos.  Rosiane, em 23/02/2026: faço contato telefõnico com o PADI de Itaboraí, que fornece e-mail para encaminhamento do laudo médico, endereço e telefones de contato de familiares. Solicito a confecção do relatório a médica Lívia, peço que nos informe quando estiver pronto. E-mail: programamelhoremcasa@itaboraí.rj.gov.br - tel: 21 97137-3551 SAD. 24/02/2026, Rosiane: vou até a pediatria retirar laudo médico para o PADI, documento ainda não está pronto. 25/02/2026, Rosiane: relatório médico encaminhado ao PADI. Em 26/02/2026, Rosiane: a mãe informa que já recebeu contato do pmec de itaboraí, que questionou a necessidade de oxigenio para SOS. Consultarei a médica Lígia a respeito.', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8388949', 'Em 09/03/2026, Rosiane: Faço contato com o Pmec e solicito informações quanto ao andamento da inclusão no programa, aguardo retorno. Em 22/04/2026, Rosiane: discuto desospitalização com a médica Caroline. Explico sobre o Pmec de Itaboraí ter informado que não realizam visita ao paciente no hospital e sugiro conversa direta da equipe médica do HFB com o Pmec.  Caroline informou que fará o contato na segunda-feira com o Pmec. A médica informa também que a paciente está internada aguardando cirurgia, mas que poderia aguardar no domicílio, pois a equipe aguarda a compra do material para realização.  Pendência: checar retorno da médica na segunda (27/04). "', NOW(), NOW())
INSERT INTO egaa_evolucao_paciente (prontuario, evolucao, created_at, updated_at) VALUES
  ('8402889', 'SESO, em 16/06/2026 - Rosiane: médica Lígia sinaliza necessidade de acompanhamento pelo EGaa, pois paciente necessitará de home care para desospitalização. Realizo abordagem à genitora, a qual relata que são municipes do RJ e que Fabiano até a internação recebia suporte do PADI. Oriento sobre a CRLS para dar entrada no home care. A mãe demonstra amplo conheimento da rede e acesso a direitos, é cadastrada no Programa Família Acolhedora, que cuida de crianças em situação de vulnerabilidade. A mãe relata que na próxima semana irá a CRLS.  Seguirá em acompanhamento pelo Egaa.', NOW(), NOW())
